<?php
declare(strict_types=1);
function index():void{require_login();require_can('blog.edit');admin_view('blog-index',['title'=>'Blogs','rows'=>db_all('SELECT p.*,c.name category,m.path cover FROM posts p LEFT JOIN post_categories c ON c.id=p.category_id LEFT JOIN media m ON m.id=p.cover_id ORDER BY p.created_at DESC')]);}
function create():void{blog_form();} function edit(string $id):void{blog_form((int)$id);}
function blog_form(?int $id=null):void{require_login();require_can('blog.edit');$post=$id?db_one('SELECT * FROM posts WHERE id=?',[$id]):null;if($id&&!$post){http_response_code(404);admin_view('error',['code'=>404,'title'=>'Post not found','message'=>'That article does not exist.']);return;}admin_view('blog-form',['title'=>$id?'Edit article':'New article','post'=>$post,'categories'=>db_all('SELECT * FROM post_categories ORDER BY sort,name'),'media'=>db_all("SELECT id,path,alt FROM media WHERE alt<>'' ORDER BY created_at DESC")]);}
function store():never{blog_save();} function update(string $id):never{blog_save((int)$id);}
function blog_save(?int $id=null):never{require_login();require_can('blog.edit');$title=(string)input('title','');$slug=trim((string)input('slug',''));$slug=$slug!==''?$slug:strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$title)??'','-'));if($title===''||$slug===''){flash('error','Title and URL slug are required.');redirect(admin_url('blog'.($id?'/'.$id:'/new')));}if(db_one('SELECT id FROM posts WHERE slug=? AND id<>?',[$slug,$id?:0])){flash('error','That URL slug is already used.');redirect(admin_url('blog'.($id?'/'.$id:'/new')));}$u=current_user();$published=$id?db_value('SELECT published_at FROM posts WHERE id=?',[$id]):null;$data=['title'=>$title,'slug'=>$slug,'category_id'=>(int)input('category_id','0')?:null,'excerpt'=>input('excerpt'),'body'=>input('body'),'cover_id'=>(int)input('cover_id','0')?:null,'read_minutes'=>max(1,(int)input('read_minutes','5')),'featured'=>isset($_POST['featured'])?1:0,'published_at'=>isset($_POST['published'])?($published?:now()):null,'updated_at'=>now(),'updated_by'=>$u['id']];if($id){db_update('posts',$id,$data);$action='updated';}else{$data['created_at']=now();$id=db_insert('posts',$data);$action='created';}log_activity($action,'post',(string)$id,ucfirst($action).' '.$title);flash('success','Article saved.');redirect(admin_url('blog/'.$id));}
